class Solution {
public:
    int longestCommonPrefix(vector<int>& arr1, vector<int>& arr2) {
        unordered_set<int> prefixes;
        prefixes.reserve(arr1.size() * 8);
        for (int x : arr1) {
            while (x > 0) {
                prefixes.insert(x);
                x /= 10;
            }
        }
        int ans = 0;
        for (int x : arr2) {
            while (x > 0) {
                if (prefixes.count(x)) {
                    int len = 0;
                    int t = x;
                    while (t > 0) {
                        ++len;
                        t /= 10;
                    }
                    if (len > ans) ans = len;
                    break;
                }
                x /= 10;
            }
        }
        return ans;
    }
};
